&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;7&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;전형 절차&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&amp;nbsp;&lt;/span&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;7&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;서류전형 - 전화면접 - 대면(화상)면접 – 최종 합격&lt;/span&gt;&lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;7&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;전형절차는 직무별로 다르게 운영될 수 있으며, 일정 및 상황에 따라 변동될 수 있습니다.&lt;/span&gt;&lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;7&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;전형 일정 및 결과는 지원서에 등록하신 이메일로 개별 안내 드립니다.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134245417&amp;quot;:false}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;7&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;2&quot; data-aria-level=&quot;1&quot;&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;참고 사항&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&amp;nbsp;&lt;/span&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;7&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;2&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;본 공고는 모집 완료 시 조기 마감될 수 있습니다.&lt;/span&gt;&lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;7&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;2&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;지원서 내용 중 허위사실이 있는 경우에는 합격이 취소될 수 있습니다.&lt;/span&gt;&lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;7&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;2&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;취업 보호 대상자(보훈대상자, 장애인 등)는 관련 법률에 따라 채용우대를 받을 수 있습니다.&lt;/span&gt;&lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;7&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;2&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;직급과 담당 업무 범위는 후보자의 전반적인 경력과 경험 등 제반사정을 고려하여 변경될 수 있습니다. 이러한 변경이 필요할 경우, 최종 합격 통지 전 적절한 시기에 후보자와 커뮤니케이션 될 예정입니다.&lt;/span&gt;&lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;7&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;2&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;채용 및 업무 수행과 관련하여 요구되는 법령상 자격이 갖추어지지 않은 경우 채용이 제한될 수 있습니다.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134245417&amp;quot;:false}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;개인정보 처리방침&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt; &amp;nbsp;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134245417&amp;quot;:false}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;12&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;쿠팡 그룹은 입사지원자 개인정보 처리방침(아래 링크)에 따라 귀하의 개인정보를 수집하여 처리합니다. &lt;/span&gt;&lt;a href=&quot;https://www.coupang.jobs/kr/privacy-policy/&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-charstyle=&quot;Hyperlink&quot;&gt;https://www.coupang.jobs/kr/privacy-policy&lt;/span&gt;&lt;/span&gt;&lt;/a&gt;&lt;span data-contrast=&quot;auto&quot;&gt; &amp;nbsp;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134245417&amp;quot;:false}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;서류 반환 정책&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt; &lt;span class=&quot;Apple-converted-space&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134245417&amp;quot;:false}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;ol&gt;
&lt;li data-leveltext=&quot;%1.&quot; data-font=&quot;&quot; data-listid=&quot;13&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:0,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769242&amp;quot;:[65533,0],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;%1.&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;본&lt;/span&gt;&lt;span class=&quot;Apple-converted-space&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;고지는 『채용절차의공정화에관한법률&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;』&lt;span class=&quot;Apple-converted-space&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;제11조제6항에 따른 것 입니다.&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li data-leveltext=&quot;%1.&quot; data-font=&quot;&quot; data-listid=&quot;13&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:0,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769242&amp;quot;:[65533,0],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;%1.&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;당사 채용에 응시한 구직자 중 최종 합격이 되지 못한 구직자는 『채용절차의 공정화에 관한 법률』에 따라 제출한 채용서류의 반환을 청구할 수 있음을 알려 드립니다. 다만, 홈페이지 또는 전자우편으로 제출된 경우나 구직자가 당사의 요구 없이 자발적으로 제출한 경우에는 그러하지 아니하며, 천재지변이나 그 밖에 당사에게 책임 없는 사유로 채용서류가 멸실된 경우에는 반환한 것으로 봅니다.&lt;/span&gt;&lt;/li&gt;
&lt;li data-leveltext=&quot;%1.&quot; data-font=&quot;&quot; data-listid=&quot;13&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:0,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769242&amp;quot;:[65533,0],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;%1.&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;위2항 본문에 따라 채용 서류 반환 청구를 하는 구직자는 채용 서류 반환 청구서 [채용절차의 공정화에 관한 법률 시행규칙 별지 제 3 호 서식]를 작성하여 이메일 (&lt;/span&gt;&lt;a href=&quot;mailto:recruitingops@coupang.com&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-charstyle=&quot;Hyperlink&quot;&gt;recruitingops@coupang.com&lt;/span&gt;&lt;/span&gt;&lt;/a&gt;&lt;span data-contrast=&quot;auto&quot;&gt;) 로 제출하면, 제출이 확인된 날로부터 14 일 이내에 지정한 주소지로 등기우편을 통하여 발송해 드립니다. 이 경우 등기우편요금은 수신자 부담으로 하게 되오니 유념하시기 바랍니다. &amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li data-leveltext=&quot;%1.&quot; data-font=&quot;&quot; data-listid=&quot;13&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:0,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769242&amp;quot;:[65533,0],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;%1.&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;당사는 위2항 본문에 따른 구직자의 반환 청구에 대비하여 채용 여부가 확정된 날로부터 180 일간 구직자가 제출한 채용서류 원본을 보관하게 되며, 그때까지 채용서류의 반환을 청구하지 아니할 경우에는 『개인정보 보호법』에 따라 지체 없이 채용서류 일체를 파기할 예정입니다.&lt;/span&gt;&lt;/li&gt;
&lt;li data-leveltext=&quot;%1.&quot; data-font=&quot;&quot; data-listid=&quot;13&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:0,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769242&amp;quot;:[65533,0],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;%1.&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;단, 위 1항 내지 4항의 내용은 대한민국의 노동 관계 법령이 적용되는 경우에만 적용됩니다. 그 이외의 경우에는 적용되지 않습니다.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134245417&amp;quot;:false}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ol&gt;

alven-dataiku:greenhouse:5991941004.descriptionHtml:
&lt;div class=&quot;content-intro&quot;&gt;&lt;p&gt;&lt;a href=&quot;https://www.dataiku.com/?utm_source=newswire&amp;amp;utm_medium=press-release&amp;amp;utm_campaign=PlatformforAISuccess&quot; target=&quot;_blank&quot;&gt;Dataiku&lt;/a&gt; is the Platform for AI Success, the enterprise orchestration layer for building, deploying, and governing AI. In a single environment, teams design and operate analytics, machine learning, and AI agents with the transparency, collaboration, and control enterprises require. Sitting above data platforms, cloud infrastructure, and AI services, Dataiku connects the full enterprise AI stack — empowering organizations to run AI across multi-vendor environments with centralized governance.&lt;br&gt;&lt;br&gt;The world’s leading companies rely on Dataiku to operationalize AI and run it as a true business performance engine delivering measurable value. For more, visit the Dataiku &lt;a href=&quot;https://blog.dataiku.com/?_gl=1*17edvf4*_ga*MjA1Mjk5NzY4OC4xNjY3MjMyMDUz*_ga_B3YXRYMY48*MTY2OTA1MDY5NS4xMi4xLjE2NjkwNTA2OTguNTcuMC4w&quot; target=&quot;_blank&quot;&gt;blog&lt;/a&gt;, &lt;a href=&quot;https://www.linkedin.com/company/dataiku/&quot; target=&quot;_blank&quot;&gt;LinkedIn&lt;/a&gt;, &lt;a href=&quot;https://x.com/dataiku&quot; target=&quot;_blank&quot;&gt;X&lt;/a&gt;, and &lt;a href=&quot;https://www.youtube.com/dataiku&quot; target=&quot;_blank&quot;&gt;YouTube&lt;/a&gt;.&lt;/p&gt;&lt;/div&gt;&lt;p&gt;Delivering Customer Success is an important focus for Dataiku. As a Customer Success Engineer (CSE) within our Solutions Engineering team, you’ll help Dataiku’s customers achieve meaningful outcomes with business analytics, AI/ML, and Gen AI.&amp;nbsp;&lt;/p&gt;
&lt;p&gt;In this technical and consultative customer-facing role, you’ll focus on technical programming to increase adoption through product enablement and one-to-many user engagement. You’ll leverage your understanding of enterprise analytics, high-impact communication abilities, and hands-on data science skills to add business value. This role will also partner closely with cross-functional teams, including Account Executives, Sales Engineers, and Professional Services and Partners to accelerate end-user adoption.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;How you’ll make an impact&amp;nbsp;&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Work closely with Dataiku’s customers, focusing on onboarding, increasing user adoption, retention, and satisfaction.&lt;/li&gt;
&lt;li&gt;Possess deep technical knowledge of the Dataiku platform to educate customers on best practices within the Dataiku platform.&amp;nbsp;&lt;/li&gt;
&lt;li&gt;Develop a deep understanding of customer business, use cases, and outcomes to guide their success with Dataiku&#39;s products and services.&lt;/li&gt;
&lt;li&gt;Execute demonstrations of new product features and conduct hands-on workshops in collaboration with the Sales Engineers.&amp;nbsp;&lt;/li&gt;
&lt;li&gt;Establish regular touchpoints with customers to advise users on using Dataiku for their specific business needs, including hands-on support as appropriate.&lt;/li&gt;
&lt;li&gt;Execute programs to create self-sustaining enablement and evangelism of Dataiku within customer accounts.&lt;/li&gt;
&lt;li&gt;Collaborate with Account Executives and Sales Engineers to drive customer engagements with the Dataiku platform and identify opportunities for expansion (both software and professional services) that can drive additional value for customers.&lt;/li&gt;
&lt;li&gt;Document and share the adoption status and key information to inform internal forecasting and renewal.&lt;/li&gt;
&lt;li&gt;Collaborate with other Dataiku functions (such as marketing) on capturing and sharing the customer stories publicly.&amp;nbsp;&lt;/li&gt;
&lt;li&gt;When identifying technical issues that block user adoption, coach administrators and users to initiate support tickets for timely resolution.&amp;nbsp;&lt;/li&gt;
&lt;li&gt;Stay current on Dataiku’s products, competitive landscape, and data science trends.&lt;/li&gt;
&lt;li&gt;Willingness to travel up to 25%.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;What you’ll need to be successful&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Bachelor’s degree in Data Science, Business Analytics, Statistics, Computer Science, or a related technical field.&lt;/li&gt;
&lt;li&gt;Minimum of four years of experience in sales engineering, technical or solutions consulting, post-sales technical delivery, or data science roles with a proven track record of customer trust and satisfaction.&lt;/li&gt;
&lt;li&gt;Strong written and oral presentation skills, capable of engaging both business and technical stakeholders.&lt;/li&gt;
&lt;li&gt;Strong technical, analytical, and problem-solving skills.&lt;/li&gt;
&lt;li&gt;Experience in building and operating communities of practice.&lt;/li&gt;
&lt;li&gt;Ability to navigate ambiguity, build consensus, foster accountability, and work with urgency to deliver customer outcomes.&lt;/li&gt;
&lt;li&gt;Ability to tailor messaging to personas with varying levels of technical acumen, including no-code and high-code users&lt;/li&gt;
&lt;li&gt;Dataiku advanced designer, Snowflake SnowPro Core and Databricks Business Analyst certifications preferred (not required).&lt;/li&gt;
&lt;li&gt;Preferably located within the Northeast region of the United States.&amp;nbsp;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;What will make you stand out&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Never-ending intellectual curiosity, detail-oriented, and analytical.&lt;/li&gt;
&lt;li&gt;Hands-on experience with data storage and computing infrastructure (SQL, Kubernetes, etc.) and proficiency with Python, R, SQL&lt;/li&gt;
&lt;li&gt;Knack for public speaking with appreciation for engaging with all levels of customer teams, from individual contributors to leadership.&lt;/li&gt;
&lt;li&gt;Passion for technology, the data and analytics space, and enjoyment learning new solutions, features, and functionalities, translating these into business value for customers.&lt;/li&gt;
&lt;li&gt;Experience in Analytics/AI or other enterprise software (preferred but not required).&lt;/li&gt;
&lt;/ul&gt;&lt;div class=&quot;content-pay-transparency&quot;&gt;&lt;div class=&quot;pay-input&quot;&gt;&lt;div class=&quot;description&quot;&gt;&lt;strong&gt;Compensation and Benefits&lt;/strong&gt;&lt;br&gt;
&lt;p&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;The final compensation package for this role will be determined during the interview process and is based on a variety of factors, including, but not limited to, geographic location, internal equity, education, skill set, experience and training. Eligible roles may also be entitled to receive commission or other variable compensation through Dataiku&#39;s incentive compensation program.&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;Dataiku also offers comprehensive benefits, including stock options, medical, dental, and vision plans, flexible spending accounts, pre-tax commuter benefits, a 401k company match, paid vacations and sick leave, paid parental leave, employer paid disability coverage, and additional health and wellbeing perks and benefits. Dataiku reserves the right to amend or modify employee perks and benefits at any time.&lt;/span&gt;&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;title&quot;&gt;US only national base pay ranges&lt;/div&gt;&lt;div class=&quot;pay-range&quot;&gt;&lt;span&gt;$144,000&lt;/span&gt;&lt;span class=&quot;divider&quot;&gt;&amp;mdash;&lt;/span&gt;&lt;span&gt;$152,000 USD&lt;/span&gt;&lt;/div&gt;&lt;/div&gt;&lt;/div&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;div&gt;&amp;nbsp;&lt;/div&gt;
&lt;div&gt;&lt;strong&gt;What are you waiting for!&lt;/strong&gt;&lt;/div&gt;
&lt;div&gt;At Dataiku, you&#39;ll be part of a journey to shape the ever-evolving world of AI. We&#39;re not just building a product; we&#39;re crafting the future of AI. If you&#39;re ready to make a significant impact in a company that values innovation, collaboration, and your personal growth, we can&#39;t wait to welcome you to Dataiku! And if you’d like to learn even more about working here, you can visit our &lt;a href=&quot;https://www.linkedin.com/company/dataiku/&quot;&gt;Dataiku LinkedIn page&lt;/a&gt;.&lt;/div&gt;
&lt;div&gt;&amp;nbsp;&lt;/div&gt;
&lt;div&gt;&lt;em&gt;Our practices are rooted in the idea that everyone should be treated with dignity, decency and fairness. Dataiku also believes that a diverse identity is a source of strength and allows us to optimize across the many dimensions that are needed for our success. Therefore, we are proud to be an equal opportunity employer.&amp;nbsp;All employment practices are based on business needs, without regard to race, ethnicity, gender identity or expression, sexual orientation, religion, age, neurodiversity, disability status, citizenship, veteran status or any other aspect which makes an individual unique or protected by laws and regulations in the locations where we operate. This applies to all policies and procedures related to recruitment and hiring, compensation, benefits, performance, promotion and termination and all other conditions and terms of employment. If you need assistance or an accommodation, please contact us at: &lt;/em&gt;&lt;a class=&quot;postings-link&quot; href=&quot;http://reasonable-accommodations@dataiku.com/&quot;&gt;reasonable-accommodations@dataiku.com&lt;/a&gt;&lt;/div&gt;
&lt;div&gt;&amp;nbsp;&lt;/div&gt;
&lt;div&gt;&lt;hr&gt;&lt;/div&gt;
&lt;div&gt;
&lt;div&gt;&amp;nbsp;&lt;/div&gt;
&lt;div&gt;&lt;strong&gt;Protect yourself from fraudulent recruitment activity&lt;/strong&gt;&lt;/div&gt;
&lt;div&gt;&lt;em&gt;Dataiku will never ask you for payment of any type during the interview or hiring process. Other than our video-conference application, Zoom, we will also never ask you to make purchases or download third-party applications during the process. If you experience something out of the ordinary or suspect fraudulent activity, please review our page on identifying and reporting fraudulent activity&amp;nbsp;&lt;a href=&quot;https://www.dataiku.com/legal/dataiku-recruitment-scams/&quot; target=&quot;_blank&quot;&gt;here.&lt;/a&gt;&lt;/em&gt;&lt;/div&gt;
&lt;/div&gt;&lt;/div&gt;

anthemis-tide:greenhouse:7720579003.descriptionHtml:
&lt;div class=&quot;content-intro&quot;&gt;&lt;h3&gt;&lt;strong&gt;A&lt;/strong&gt;&lt;strong&gt;BOUT TIDE&lt;/strong&gt;&lt;/h3&gt;
&lt;p&gt;At Tide, we help SMEs save time and money in the running of their businesses by not only offering business accounts and related banking services, but also a comprehensive set of highly usable and connected administrative solutions, from invoicing to accounting.&lt;/p&gt;
&lt;p&gt;Tide is transforming the small business banking market and now supports over 2 million members globally across the UK, India, Germany and France.&lt;/p&gt;
&lt;p&gt;Using advanced technology, all solutions are designed with SMEs in mind. With quick onboarding, low fees and innovative features, we thrive on making data driven decisions to serve our mission: to help SMEs save time and money so they can get back to doing what they love.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Tide facts:&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Tide is available for UK, Indian, German and French SMEs&lt;/li&gt;
&lt;li&gt;Over 2 million members: 900,000 UK and 1,100,000 in India and growing rapidly&lt;/li&gt;
&lt;li&gt;Over $300 million raised in funding&lt;/li&gt;
&lt;li&gt;Over 2,800 Tideans globally&lt;/li&gt;
&lt;li&gt;Recognised with Great Place to Work certification three years in a row, and among India’s Top 50 Best Workplaces in Banking, Financial Services, and Insurance in 2026&lt;/li&gt;
&lt;li&gt;We have offices in Central London, with a member support and technology centre in Sofia, Bulgaria, technology centres in Serbia, Romania, Lithuania and Hyderabad and offices in Gurugram, New Delhi, Berlin, Paris and Luxembourg&lt;/li&gt;
&lt;/ul&gt;&lt;/div&gt;&lt;p&gt;&lt;/p&gt;
&lt;h3&gt;ABOUT THE ROLE:&lt;/h3&gt;
&lt;p&gt;It’s exciting times here at Tide, we are scaling and developing our product offering at a phenomenal rate and have made our first step into our ambitious plans towards international expansion with our move into the Indian SME marketplace. We need someone to be proactive, take initiative and build out best in class financial reporting and control processes and procedures for our Indian operations.&lt;/p&gt;
&lt;p&gt;As our new Revenue Controller you’ll report to the Director of Finance and be responsible for the financial controllership of our Indian entities.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;As a&amp;nbsp; Senior Revenue Controller you’ll be:&lt;/strong&gt;&lt;strong&gt;&amp;nbsp;&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Understand and reconcile various revenue lines with proper back up workings, system data and vendor confirmations&amp;nbsp;&lt;/li&gt;
&lt;li&gt;Manage monthly revenue close activities, including revenue recognition, accruals, reconciliations, and preparation of supporting schedules.&lt;/li&gt;
&lt;li&gt;Ensure timely and accurate reporting of revenue performance, key metrics, balance sheet reconciliations, and management information for internal and external stakeholders.&lt;/li&gt;
&lt;li&gt;Own the end-to-end revenue accounting and controllership processes, ensuring completeness, accuracy, and compliance with applicable accounting standards (IFRS/Ind AS).&lt;/li&gt;
&lt;li&gt;Develop and maintain robust revenue control frameworks, ensuring strong governance and adherence to internal policies and procedures.&lt;/li&gt;
&lt;li&gt;Perform detailed analysis of revenue streams, product profitability, transaction volumes, and trends to identify risks, anomalies, and growth opportunities.&lt;/li&gt;
&lt;li&gt;Partner closely with Product, Operations, Treasury, FP&amp;amp;A, and Commercial teams to understand new products, pricing structures, and business initiatives, ensuring appropriate accounting treatment and revenue recognition.&lt;/li&gt;
&lt;li&gt;Support the implementation and enhancement of automated revenue processes and scalable finance systems to improve efficiency and strengthen controls.&lt;/li&gt;
&lt;li&gt;Own reconciliation processes across banking partners, payment processors, card schemes, and other third-party service providers, ensuring timely resolution of exceptions.&lt;/li&gt;
&lt;li&gt;Collaborate with the Group Finance and Financial Reporting teams to ensure consistency with global accounting policies and reporting requirements.&lt;/li&gt;
&lt;li&gt;Prepare and review revenue-related balance sheet reconciliations and ensure proper documentation for significant transactions and accounting judgments.&lt;/li&gt;
&lt;li&gt;Support budgeting, forecasting, and variance analysis activities by providing insights into revenue drivers and business performance.&lt;/li&gt;
&lt;li&gt;Lead internal and external audits relating to revenue processes and controls, ensuring timely closure of observations and recommendations.&lt;/li&gt;
&lt;li&gt;Identify opportunities for process optimization, automation, and continuous improvement to enhance accuracy, scalability, and operational efficiency.&lt;/li&gt;
&lt;li&gt;Contribute to strategic initiatives, new product launches, and business expansion projects by providing commercial and financial insights from a revenue perspective.&lt;/li&gt;
&lt;li&gt;Thrive in a fast-paced fintech environment, taking ownership of business-critical processes and driving best-in-class revenue operations.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;What makes you a great fit:&amp;nbsp;&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Experience working in fintech or payment services. Experience of lending will be a plus&amp;nbsp;&lt;/li&gt;
&lt;li&gt;Strong financial acumen and excellent technical accounting skills. Familiar with accounting standard and disclosure requirements under Indian GAAP and/or IFRS&lt;/li&gt;
&lt;li&gt;Experienced in dealing with the statutory audit of financial services company&lt;/li&gt;
&lt;li&gt;You hold a professional finance qualification (CA/CMA) or Post graduation in Finance with strong relevant exposure.&lt;/li&gt;
&lt;li&gt;5 to 8 years PQE&lt;/li&gt;
&lt;li&gt;Confident dealing with senior stakeholders across the business and owning your work with minimal hands-on management&lt;/li&gt;
&lt;li&gt;Commercial acumen&lt;/li&gt;
&lt;li&gt;Meticulous attention to detail&lt;/li&gt;
&lt;li&gt;Ability to take responsibility for business-critical financial operations&lt;/li&gt;
&lt;li&gt;Exceptional organisational skills&lt;/li&gt;
&lt;li&gt;Curious mind and high level of problem solving capability&lt;/li&gt;
&lt;li&gt;Motivated by making a difference and getting things done&lt;/li&gt;
&lt;li&gt;You would like to work in a fast-paced, startup environment&lt;/li&gt;
&lt;li&gt;Personable, and able to build strong working relationships&lt;/li&gt;
&lt;li&gt;Tech savvy&lt;/li&gt;
&lt;li&gt;Hold a degree from a top-tier university&lt;/li&gt;
&lt;/ul&gt;
&lt;h3&gt;&amp;nbsp;&lt;/h3&gt;
&lt;p&gt;&lt;strong&gt;What you’ll get in return:&amp;nbsp;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;Make work, work for you! We are embracing new ways of working and support flexible working arrangements. With our Working Out of Office (WOO) policy our colleagues can work remotely from home or anywhere in their home country. Additionally, you can work from a different country for up to 90 days a year. Plus, you’ll get:&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Competitive salary&amp;nbsp;&lt;/li&gt;
&lt;li&gt;Self &amp;amp; family health insurance&lt;/li&gt;
&lt;li&gt;Term &amp;amp; life insurance&lt;/li&gt;
&lt;li&gt;OPD benefits&lt;/li&gt;
&lt;li&gt;Mental wellbeing through Plumm&lt;/li&gt;
&lt;li&gt;Learning &amp;amp; development budget&lt;/li&gt;
&lt;li&gt;WFH setup allowance&lt;/li&gt;
&lt;li&gt;25 annual leaves&lt;/li&gt;
&lt;li&gt;Family &amp;amp; friendly leaves&lt;/li&gt;
&lt;li&gt;Stock options&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;h3&gt;TIDEAN WAYS OF WORKING&lt;/h3&gt;
&lt;p&gt;At Tide, we champion a &lt;strong&gt;flexible workplace &lt;/strong&gt;model that&lt;strong&gt; &lt;/strong&gt;supports both in-person and remote work to cater to the specific needs of our different teams.&amp;nbsp;&lt;/p&gt;
&lt;p&gt;While remote work is supported, we believe in the power of face-to-face interactions to foster team spirit and collaboration. Our offices are designed as hubs for innovation and team-building, where we encourage regular in-person gatherings to foster a strong sense of community.&lt;/p&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;h3&gt;TIDE IS A PLACE FOR EVERYONE&lt;/h3&gt;
&lt;p&gt;At Tide, we believe that we can only succeed if we let our differences enrich our culture. Our Tideans come from a variety of backgrounds and experience levels. We consider everyone irrespective of their ethnicity, religion, sexual orientation, gender identity, family or parental status, national origin, veteran, neurodiversity or differently-abled status. We celebrate diversity in our workforce as a cornerstone of our success. Our commitment to a broad spectrum of ideas and backgrounds is what enables us to build products that resonate with our members’ diverse needs and lives.&amp;nbsp;&lt;/p&gt;
&lt;p&gt;We are One Team and foster a transparent and inclusive environment, where everyone’s voice is heard.&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;em&gt;At Tide, we thrive on diversity, embracing various backgrounds and experiences. We welcome all individuals regardless of ethnicity, religion, sexual orientation, gender identity, or disability. Our inclusive culture is key to our success, helping us build products that meet our members&#39; diverse needs. We are One Team, committed to transparency and ensuring everyone’s voice is heard.&lt;/em&gt;&lt;/p&gt;
&lt;div class=&quot;p-rich_text_section&quot;&gt;&amp;nbsp;&lt;/div&gt;
&lt;div class=&quot;p-rich_text_section&quot;&gt;&lt;strong&gt;Disclaimer&lt;/strong&gt;&lt;/div&gt;
&lt;div class=&quot;p-rich_text_section&quot;&gt;&amp;nbsp;&lt;/div&gt;
&lt;div class=&quot;p-rich_text_section&quot;&gt;&lt;em&gt;It has come to our attention that individuals or agencies are falsely claiming to represent Tide and are reaching out to candidates regarding job opportunities. Please be aware that:&lt;/em&gt;&lt;/div&gt;
&lt;ul class=&quot;p-rich_text_list p-rich_text_list__bullet p-rich_text_list--nested&quot; data-stringify-type=&quot;unordered-list&quot; data-list-tree=&quot;true&quot; data-indent=&quot;0&quot; data-border=&quot;0&quot;&gt;
&lt;li style=&quot;font-style: italic;&quot; data-stringify-indent=&quot;0&quot; data-stringify-border=&quot;0&quot;&gt;&lt;em&gt;Tide does&amp;nbsp;&lt;strong data-stringify-type=&quot;bold&quot;&gt;not&lt;/strong&gt;&amp;nbsp;charge any fees at any stage of the recruitment process.&lt;/em&gt;&lt;/li&gt;
&lt;li style=&quot;font-style: italic;&quot; data-stringify-indent=&quot;0&quot; data-stringify-border=&quot;0&quot;&gt;&lt;em&gt;All official Tide job opportunities are listed exclusively on our&amp;nbsp;&lt;a href=&quot;https://www.tide.co/careers/&quot; target=&quot;_blank&quot;&gt;&lt;strong data-stringify-type=&quot;bold&quot;&gt;Careers Page&lt;/strong&gt;&lt;/a&gt;&amp;nbsp;and applications should be submitted through this channel.&lt;/em&gt;&lt;/li&gt;
&lt;li style=&quot;font-style: italic;&quot; data-stringify-indent=&quot;0&quot; data-stringify-border=&quot;0&quot;&gt;&lt;em&gt;Communication from Tide will only come from an official&amp;nbsp;&lt;strong data-stringify-type=&quot;bold&quot;&gt;@tide&lt;/strong&gt;&lt;strong data-stringify-type=&quot;bold&quot;&gt;.co&lt;/strong&gt;&amp;nbsp;email address.&lt;/em&gt;&lt;/li&gt;
&lt;li style=&quot;font-style: italic;&quot; data-stringify-indent=&quot;0&quot; data-stringify-border=&quot;0&quot;&gt;&lt;em&gt;Tide does not work with agencies or recruiters without prior formal engagement, and we do not authorize third parties to make job offers on our behalf.&lt;/em&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;em&gt;If you are contacted by anyone misrepresenting Tide or requesting payment, please treat it as fraudulent and report it to us immediately at &lt;a href=&quot;mailto:talent@tide.co&quot; target=&quot;_blank&quot;&gt;talent@tide.co&lt;/a&gt;&lt;br&gt;Your safety and trust are important to us, and we are committed to ensuring a fair and transparent recruitment process.&lt;/em&gt;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;em&gt;&lt;em data-stringify-type=&quot;italic&quot;&gt;Tide leverages AI to enhance our hiring experience. You can read more about how we use AI in our recruitment process in our &lt;a href=&quot;https://assets.ctfassets.net/3h69mkdgxn20/5MFtWSdG8YLKq3jZkK52NY/3f18633073e6cdbd03bba4b9791c64f4/Using_AI_throughout_the_Hiring_Process.pdf&quot; target=&quot;_blank&quot;&gt;AI Policy&lt;/a&gt;.&lt;/em&gt;&lt;/em&gt;&lt;/p&gt;
&lt;p&gt;&lt;em&gt;&lt;em data-stringify-type=&quot;italic&quot;&gt;Your personal data will be processed by Tide for recruitment purposes and in accordance with &lt;/em&gt;&lt;em data-stringify-type=&quot;italic&quot;&gt;&lt;a class=&quot;c-link&quot; href=&quot;https://assets.ctfassets.net/3h69mkdgxn20/4TE0uAE3SXomATDVneocNA/aa31893960b4064dd406ad15d029dcd3/Recruitment_Privacy_Notice.pdf&quot; target=&quot;_blank&quot; data-stringify-link=&quot;https://assets.ctfassets.net/3h69mkdgxn20/1MYf6q4ZMWugpeaROVETBN/526e9c160a2de03576413c81657c6466/Recruitment_Privacy_Notice__Final_Draft__Sep_2024_.pdf&quot; data-sk=&quot;tooltip_parent&quot;&gt;Tide&#39;s Recruitment Privacy Notice&lt;/a&gt;&lt;/em&gt;&lt;em data-stringify-type=&quot;italic&quot;&gt;.&lt;/em&gt;&lt;/em&gt;&lt;/p&gt;&lt;/div&gt;

anthemis-tide:greenhouse:7770013003.descriptionHtml:
&lt;div class=&quot;content-intro&quot;&gt;&lt;h3&gt;&lt;strong&gt;A&lt;/strong&gt;&lt;strong&gt;BOUT TIDE&lt;/strong&gt;&lt;/h3&gt;
&lt;p&gt;At Tide, we help SMEs save time and money in the running of their businesses by not only offering business accounts and related banking services, but also a comprehensive set of highly usable and connected administrative solutions, from invoicing to accounting.&lt;/p&gt;
&lt;p&gt;Tide is transforming the small business banking market and now supports over 2 million members globally across the UK, India, Germany and France.&lt;/p&gt;
&lt;p&gt;Using advanced technology, all solutions are designed with SMEs in mind. With quick onboarding, low fees and innovative features, we thrive on making data driven decisions to serve our mission: to help SMEs save time and money so they can get back to doing what they love.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Tide facts:&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Tide is available for UK, Indian, German and French SMEs&lt;/li&gt;
&lt;li&gt;Over 2 million members: 900,000 UK and 1,100,000 in India and growing rapidly&lt;/li&gt;
&lt;li&gt;Over $300 million raised in funding&lt;/li&gt;
&lt;li&gt;Over 2,800 Tideans globally&lt;/li&gt;
&lt;li&gt;Recognised with Great Place to Work certification three years in a row, and among India’s Top 50 Best Workplaces in Banking, Financial Services, and Insurance in 2026&lt;/li&gt;
&lt;li&gt;We have offices in Central London, with a member support and technology centre in Sofia, Bulgaria, technology centres in Serbia, Romania, Lithuania and Hyderabad and offices in Gurugram, New Delhi, Berlin, Paris and Luxembourg&lt;/li&gt;
&lt;/ul&gt;&lt;/div&gt;&lt;h3&gt;ABOUT THE ROLE:&lt;/h3&gt;
&lt;p&gt;We are seeking a highly quantitative, commercially-minded Senior Operations Manager to sit at the absolute intersection of Operations, Product, and Corporate Finance (FP&amp;amp;A).&lt;/p&gt;
&lt;p&gt;In this critical role, your primary identity isn&#39;t compliance—i&lt;strong&gt;t&#39;s unit economics and cross-functional execution&lt;/strong&gt;. You will serve as the &lt;strong&gt;dedicated operational glue&lt;/strong&gt; ensuring our customer acquisition funnel, vendor cost bases, and product rollouts perfectly align with our financial forecasting models.&lt;br&gt;&lt;br&gt;You will be the proactive driver who meets regularly with Product and Operations to extract insights on upcoming, planned, and live initiatives, compressing that operational reality into clear data inputs for FP&amp;amp;A modeling. You will own the tracking of operational actuals, monitor global unit costs against efficiency targets, and assess the commercial impact of all KYC initiatives.&lt;/p&gt;
&lt;p&gt;Simultaneously, you will act as a premier project manager for the Business Operations team—capable of leading high-stakes operational initiatives, from deploying new product updates to launching entirely new geographical markets.&lt;/p&gt;
&lt;p&gt;If you are an exceptional stakeholder manager who can translate operational velocity into clear financial implications, manage cross-functional timelines, and navigate ambiguity, this role offers a direct runway for growth.&lt;/p&gt;
&lt;h3&gt;ON THIS ROLE, YOU&#39;LL BE:&lt;/h3&gt;
&lt;h4&gt;&lt;strong&gt;1. Commercial Tracking &amp;amp; FP&amp;amp;A Partnership (Primary Focus)&lt;/strong&gt;&lt;strong&gt;&lt;br&gt;&lt;/strong&gt;&lt;/h4&gt;
&lt;ul&gt;
&lt;li&gt;Proactively map, track, and collate all upcoming product roadmaps, features, and departmental OKRs across different markets that carry a potential cost or capacity impact.&lt;/li&gt;
&lt;li&gt;Establish a regular cadence with Product and Operations teams to extract operational insights on planned and live initiatives. Compress these complex, moving updates into structured, predictable data inputs for FP&amp;amp;A forecasting models.&lt;/li&gt;
&lt;li&gt;Rigorously monitor and track unit costs across different markets and SaaS vendor segments against strict efficiency targets to identify sub-optimal financial performance.&lt;/li&gt;
&lt;li&gt;Analyze and evaluate the real-world commercial impact, ROI, and efficiency gains of product updates and operational process changes.&lt;/li&gt;
&lt;li&gt;Support the corporate FP&amp;amp;A team by regularly updating operational actuals, tracking vendor billing/usage patterns, and maintaining departmental headcount and resource models.&lt;/li&gt;
&lt;li&gt;Manipulate operational data using Excel and visualization tools to provide actionable commercial insights to senior leadership.&lt;/li&gt;
&lt;/ul&gt;
&lt;h4&gt;&lt;strong&gt;2. End-to-End Project Management &amp;amp; Strategic Launches&lt;/strong&gt;&lt;/h4&gt;
&lt;ul&gt;
&lt;li&gt;Act as the lead non-technical project manager for critical operations projects, including scaling into new European markets and localizing onboarding frameworks.&lt;/li&gt;
&lt;li&gt;Seamlessly bridge communication gaps and drive alignment between Operations, Product, Marketing, Legal, Compliance, and Finance.&lt;/li&gt;
&lt;li&gt;Own project roadmaps, drive accountability across technical and non-technical teams, manage external vendor timelines, and proactively mitigate risks to keep launches on schedule.&lt;/li&gt;
&lt;/ul&gt;
&lt;h4&gt;&lt;strong&gt;3. Core BizOps &amp;amp; Stakeholder Alignment&lt;/strong&gt;&lt;/h4&gt;
&lt;ul&gt;
&lt;li&gt;Translate complex operational metrics, capacity constraints, and process variances into clear, compelling narratives for corporate leadership.&lt;/li&gt;
&lt;li&gt;Maintain a true &quot;BizOps&quot; mindset—building scalable, documented processes, designing performance dashboards, and solving complex problems as a generalist.&lt;/li&gt;
&lt;/ul&gt;
&lt;h3&gt;WHAT WE ARE LOOKING FOR:&amp;nbsp;&lt;/h3&gt;
&lt;ul&gt;
&lt;li&gt;5+ years of experience in a fast-paced environment such as FinTech, Investment Banking, Management Consulting, Business Operations, or Finance Business Partnering.&lt;/li&gt;
&lt;li&gt;You don&#39;t need to be building financial models from scratch, but you must have a strong &quot;way with numbers&quot;—deeply comfortable working with data, updating headcount/budget inputs, and tracking KPIs.&lt;/li&gt;
&lt;li&gt;A track record of successfully managing complex, multi-stakeholder project timelines and delivering cross-functional outcomes (e.g., product or market launches).&lt;/li&gt;
&lt;li&gt;Exceptional proficiency in Excel/Google Sheets is required. Experience with data visualization/BI platforms (e.g., Looker, SQL) is highly advantageous.&lt;/li&gt;
&lt;li&gt;A proven ability to partner with corporate leadership, push back constructively using data, and keep diverse technical and non-technical teams aligned.&lt;/li&gt;
&lt;li&gt;Degree in Finance, Accounting, Economics, Mathematics, or a highly analytical business/engineering field.&lt;/li&gt;
&lt;li&gt;Fluent English is required. Additional European languages (German, French, or Italian) are advantageous.&lt;/li&gt;
&lt;li&gt;Operational experience in KYC, or regulated SaaS environments is a plus, but a strong commercial mindset and data literacy are prioritized.&lt;/li&gt;
&lt;/ul&gt;
&lt;h3&gt;WHAT YOU’LL GET IN RETURN:&amp;nbsp;&lt;/h3&gt;
&lt;ul&gt;
&lt;li data-renderer-start-pos=&quot;4162&quot;&gt;25 days paid annual leave&amp;nbsp;&lt;/li&gt;
&lt;li data-renderer-start-pos=&quot;4162&quot;&gt;3 paid days off for volunteering or&amp;nbsp;&lt;span data-highlighted=&quot;true&quot; data-vc=&quot;highlighted-text&quot;&gt;&lt;span class=&quot;_kqswh2mm&quot;&gt;&lt;span class=&quot;_5pioz8co _189e1dm9 _1il9buyh _19lc184f _d0altlke&quot; data-testid=&quot;definition-highlighter&quot;&gt;L&amp;amp;D&lt;/span&gt;&lt;/span&gt;&lt;/span&gt; activities&lt;/li&gt;
&lt;li data-renderer-start-pos=&quot;4162&quot;&gt;Extended maternity and paternity leave covered by the company&lt;/li&gt;
&lt;li data-renderer-start-pos=&quot;4162&quot;&gt;Personal &lt;span data-highlighted=&quot;true&quot; data-vc=&quot;highlighted-text&quot;&gt;L&amp;amp;D&lt;/span&gt; budget&lt;/li&gt;
&lt;li data-renderer-start-pos=&quot;4162&quot;&gt;Additional health &amp;amp; dental insurance&lt;/li&gt;
&lt;li data-renderer-start-pos=&quot;4162&quot;&gt;Mental wellbeing platform&amp;nbsp;&lt;/li&gt;
&lt;li data-renderer-start-pos=&quot;4162&quot;&gt;Multisport Card&lt;/li&gt;
&lt;li data-renderer-start-pos=&quot;4162&quot;&gt;Food Vouchers&lt;/li&gt;
&lt;li data-renderer-start-pos=&quot;4162&quot;&gt;Snacks, light food, drinks in the office&lt;/li&gt;
&lt;li data-renderer-start-pos=&quot;4162&quot;&gt;&lt;span data-highlighted=&quot;true&quot; data-vc=&quot;highlighted-text&quot;&gt;&lt;span class=&quot;_kqswh2mm&quot;&gt;&lt;span class=&quot;_5pioz8co _189e1dm9 _1il9buyh _19lc184f _d0altlke&quot; data-testid=&quot;definition-highlighter&quot;&gt;WFH&lt;/span&gt;&lt;/span&gt;&lt;/span&gt; equipment allowance&lt;/li&gt;
&lt;li data-renderer-start-pos=&quot;4162&quot;&gt;Flexible working from home&lt;/li&gt;
&lt;li data-renderer-start-pos=&quot;4162&quot;&gt;Sabbatical Leave&lt;/li&gt;
&lt;li data-renderer-start-pos=&quot;4162&quot;&gt;Stock Options&lt;/li&gt;
&lt;li data-renderer-start-pos=&quot;4162&quot;&gt;Salary: €40,400 to €45,450&lt;/li&gt;
&lt;/ul&gt;
&lt;h3&gt;TIDEAN WAYS OF WORKING&lt;/h3&gt;
&lt;p&gt;At Tide, we champion a &lt;strong&gt;flexible workplace &lt;/strong&gt;model that&lt;strong&gt; &lt;/strong&gt;supports both in-person and remote work to cater to the specific needs of our different teams.&amp;nbsp;&lt;/p&gt;
&lt;p&gt;While remote work is supported, we believe in the power of face-to-face interactions to foster team spirit and collaboration. Our offices are designed as hubs for innovation and team-building, where we encourage regular in-person gatherings to foster a strong sense of community.&lt;/p&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;h3&gt;TIDE IS A PLACE FOR EVERYONE&lt;/h3&gt;
&lt;p&gt;At Tide, we believe that we can only succeed if we let our differences enrich our culture. Our Tideans come from a variety of backgrounds and experience levels. We consider everyone irrespective of their ethnicity, religion, sexual orientation, gender identity, family or parental status, national origin, veteran, neurodiversity or differently-abled status. We celebrate diversity in our workforce as a cornerstone of our success. Our commitment to a broad spectrum of ideas and backgrounds is what enables us to build products that resonate with our members’ diverse needs and lives.&amp;nbsp;&lt;/p&gt;
&lt;p&gt;We are One Team and foster a transparent and inclusive environment, where everyone’s voice is heard.&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;em&gt;At Tide, we thrive on diversity, embracing various backgrounds and experiences. We welcome all individuals regardless of ethnicity, religion, sexual orientation, gender identity, or disability. Our inclusive culture is key to our success, helping us build products that meet our members&#39; diverse needs. We are One Team, committed to transparency and ensuring everyone’s voice is heard.&lt;/em&gt;&lt;/p&gt;
&lt;div class=&quot;p-rich_text_section&quot;&gt;&amp;nbsp;&lt;/div&gt;
&lt;div class=&quot;p-rich_text_section&quot;&gt;&lt;strong&gt;Disclaimer&lt;/strong&gt;&lt;/div&gt;
&lt;div class=&quot;p-rich_text_section&quot;&gt;&amp;nbsp;&lt;/div&gt;
&lt;div class=&quot;p-rich_text_section&quot;&gt;&lt;em&gt;It has come to our attention that individuals or agencies are falsely claiming to represent Tide and are reaching out to candidates regarding job opportunities. Please be aware that:&lt;/em&gt;&lt;/div&gt;
&lt;ul class=&quot;p-rich_text_list p-rich_text_list__bullet p-rich_text_list--nested&quot; data-stringify-type=&quot;unordered-list&quot; data-list-tree=&quot;true&quot; data-indent=&quot;0&quot; data-border=&quot;0&quot;&gt;
&lt;li style=&quot;font-style: italic;&quot; data-stringify-indent=&quot;0&quot; data-stringify-border=&quot;0&quot;&gt;&lt;em&gt;Tide does&amp;nbsp;&lt;strong data-stringify-type=&quot;bold&quot;&gt;not&lt;/strong&gt;&amp;nbsp;charge any fees at any stage of the recruitment process.&lt;/em&gt;&lt;/li&gt;
&lt;li style=&quot;font-style: italic;&quot; data-stringify-indent=&quot;0&quot; data-stringify-border=&quot;0&quot;&gt;&lt;em&gt;All official Tide job opportunities are listed exclusively on our&amp;nbsp;&lt;a href=&quot;https://www.tide.co/careers/&quot; target=&quot;_blank&quot;&gt;&lt;strong data-stringify-type=&quot;bold&quot;&gt;Careers Page&lt;/strong&gt;&lt;/a&gt;&amp;nbsp;and applications should be submitted through this channel.&lt;/em&gt;&lt;/li&gt;
