&lt;li style=&quot;font-family: tahoma, arial, helvetica, sans-serif;&quot; data-start=&quot;2060&quot; data-end=&quot;2154&quot;&gt;
&lt;p data-start=&quot;2062&quot; data-end=&quot;2154&quot;&gt;&lt;span style=&quot;font-family: tahoma, arial, helvetica, sans-serif;&quot;&gt;&lt;strong data-start=&quot;2062&quot; data-end=&quot;2086&quot;&gt;Revenue Performance:&lt;/strong&gt;&lt;span class=&quot;Apple-converted-space&quot;&gt;&amp;nbsp;&lt;/span&gt;Consistently meet or exceed federal sales targets and defined KPIs.&lt;/span&gt;&lt;/p&gt;
